head.script:
scwin.onpageload = function() {
    sbx_modal.setValue("false");
};
scwin.onpageunload = function() {};
scwin.btn_openWFramePopup1_onclick = function(e) {
    scwin.openPopup("wframePopup");
};
scwin.btn_openIFramePopup_onclick = function(e) {
    scwin.openPopup("iframePopup");
};
scwin.btn_openBrowserPopup_onclick = function(e) {
    scwin.openPopup("browserPopup");
};
scwin.btn_getPopupWindow_onclick = function(e) {
    var a = $p.getPopupList(true);
    $p.closePopup(a[0].id);
};
scwin.openPopup = function(type, cmodal) {
    var top = "100px";
    var left = "100px";
    var locPosition = $p.top().scwin.popupIdx % 3;
    var modal = true;
    if (sbx_modal.getValue() === "false") {
        modal = false;
    }
    var frameModal = sbx_frame.getValue();
    if (frameModal === "tac_main") {
        //frameModal = $p.getFrame().getParentFrame().getParentFrame().id;
        frameModal = $p.getFrame().getParentFrame().id;
    } else if (frameModal === "windowContainer1") {
        frameModal = $p.getFrame().id;
    }
    switch (locPosition) {
        case 0:
            top = "100px";
            left = "100px";
            break;
        case 1:
            top = "370px";
            left = "400px";
            break;
        case 2:
            top = "100px";
            left = "700px";
            break;
        default:
    }
    var popupName = (type + "_depth1__" + $p.top().scwin.popupIdx) || ("wframePopup" + $p.top().scwin.popupIdx);
    if (modal === true) {
        popupName += " (modal)";
    } else {
        popupName += " (modaless)";
    }
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var options = {
        id: "popup" + $p.top().scwin.popupIdx,
        //id : "popup",
        type: type,
        width: "580px",
        height: "250px",
        top: "600px",
        left: "10px",
        popupName: popupName,
        modal: cmodal ? cmodal : modal,
        useModalStack: true,
        useModalDisable: false,
        frameModal: frameModal,
        processMsgFrame: true,
        //windowMoveType : "overflow",
        resizable: true,
        useMaximize: false,
        status: true,
        menubar: false,
        windowDragMove: true,
        scrollbars: false,
        title: false
    };
    $p.openPopup("tabControl.xml", options);
    $p.top().scwin.popupIdx++;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
